<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"
import { ElMessage } from "element-plus"
import { bidApi } from "../../api/bid"
import { HttpError } from "../../shared/http"
import { useAuthStore } from "../../stores/auth"
import { IMPORT_STATUS_LABELS, PROJECT_STATUS_LABELS, type BidProjectStatus } from "../../types/bid"
const auth = useAuthStore(); const loading = ref(false); const submitting = ref(false); const projects = ref<any[]>([]); const total = ref(0); const page = ref(1); const pageSize = ref(50); const filters = reactive({ keyword: "", status: undefined as BidProjectStatus | undefined }); const createVisible = ref(false); const file = ref<File>(); const form = reactive({ project_name: "", buyer_name: "", start_at: "", deadline_at: "", remark: "" })
async function load(target = page.value) { loading.value = true; try { const result = await bidApi.list({ page: target, page_size: pageSize.value, keyword: filters.keyword.trim() || undefined, status: filters.status }); projects.value = result.items; total.value = result.total; page.value = result.page } catch (e) { ElMessage.error(e instanceof HttpError ? e.response.message : "加载项目列表失败") } finally { loading.value = false } }
function chooseFile(upload: any) { const candidate = upload.raw as File; if (!candidate.name.toLowerCase().endsWith(".xlsx")) return ElMessage.error("目前仅支持 .xlsx 文件"); if (candidate.size > 25 * 1024 * 1024) return ElMessage.error("Excel 文件不能超过 25 MB"); file.value = candidate }
async function create() { if (!file.value || !form.project_name.trim() || !form.buyer_name.trim()) return ElMessage.error("请填写必填项并选择 Excel 文件"); if (form.start_at && form.deadline_at && form.start_at > form.deadline_at) return ElMessage.error("开始时间不能晚于截止时间"); submitting.value = true; try { const result = await bidApi.create({ ...form, project_name: form.project_name.trim(), buyer_name: form.buyer_name.trim(), file: file.value }); const message = result.import_status === "PARSED" ? "项目创建成功，Excel 已解析，可以开始商品匹配。" : result.import_status === "MAPPING_REQUIRED" ? "项目已创建，但当前 Excel 未识别到模板，需要完成模板配置。" : `项目已创建，但 Excel 解析失败：${result.import_error ?? "未知错误"}`; ElMessage.success(message); createVisible.value = false; await load(1) } catch (e) { ElMessage.error(e instanceof HttpError ? e.response.message : "创建项目失败") } finally { submitting.value = false } }
onMounted(() => void load())
</script>
<template><div class="bid-page"><header><div><p>BID PROJECTS</p><h1>投标项目</h1><span>每个客户 Excel 对应一个投标项目，需求行与文件版本均可追溯。</span></div><el-button v-if="auth.hasPermission('bid:create')" type="primary" @click="createVisible=true">新建项目</el-button></header><el-card><el-form inline @submit.prevent="load(1)"><el-input v-model="filters.keyword" clearable placeholder="搜索项目编号或项目名称" @change="load(1)"/><el-select v-model="filters.status" clearable placeholder="全部状态" @change="load(1)"><el-option v-for="(label,key) in PROJECT_STATUS_LABELS" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="load(1)">查询</el-button></el-form></el-card><el-card><el-table v-loading="loading" :data="projects"><el-table-column prop="project_code" label="项目编号" min-width="130"/><el-table-column prop="project_name" label="项目名称" min-width="180"/><el-table-column prop="buyer_name" label="需求商" min-width="150"/><el-table-column label="项目状态"><template #default="{row}"><el-tag>{{ PROJECT_STATUS_LABELS[row.status] }}</el-tag></template></el-table-column><el-table-column label="导入状态"><template #default="{row}">{{ IMPORT_STATUS_LABELS[row.import_status] }}</template></el-table-column><el-table-column prop="total_item_count" label="需求总数"/><el-table-column prop="processed_item_count" label="匹配处理数"/><el-table-column prop="start_at" label="开始时间" min-width="170"/><el-table-column prop="deadline_at" label="截止时间" min-width="170"/><el-table-column prop="created_at" label="创建时间" min-width="170"/><el-table-column label="操作"><template #default="{row}"><RouterLink :to="`/bid-projects/${row.id}`"><el-button link type="primary">详情</el-button></RouterLink></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" :total="total" @current-change="load" @size-change="()=>load(1)"/></el-card><el-dialog v-model="createVisible" title="新建投标项目" width="min(860px, 92vw)" class="create-project-dialog"><el-alert title="目前仅支持 .xlsx 文件，最大 25 MB。" type="info" :closable="false"/><el-alert v-if="submitting" title="正在上传并解析 Excel，请稍候。" type="info" :closable="false" class="submitting-notice"/><el-form label-position="top" class="create-project-form"><el-form-item label="项目名称 *"><el-input v-model="form.project_name"/></el-form-item><el-form-item label="需求商 *"><el-input v-model="form.buyer_name"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.start_at" value-format="YYYY-MM-DDTHH:mm:ss" type="datetime"/></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="form.deadline_at" value-format="YYYY-MM-DDTHH:mm:ss" type="datetime"/></el-form-item><el-form-item label="Excel 文件 *" class="upload-field"><el-upload :auto-upload="false" :limit="1" accept=".xlsx" :on-change="chooseFile"><el-button>选择 .xlsx 文件</el-button><span v-if="file" class="selected-file-name">{{ file.name }}</span></el-upload></el-form-item><el-form-item label="备注" class="remark-field"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><div class="create-project-footer"><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="create">创建项目</el-button></div></template></el-dialog></div></template>
<style scoped>.bid-page{display:grid;gap:18px}.bid-page header{display:flex;justify-content:space-between;align-items:start;padding:24px 28px;border-radius:14px;background:#edf5ff}.bid-page h1{margin:4px 0}.bid-page p{margin:0;color:#2670ca;font-weight:bold}.el-form{display:flex;gap:12px}.el-pagination{justify-content:end;margin-top:16px}.submitting-notice{margin-top:12px}.create-project-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 24px;margin-top:20px}.create-project-form :deep(.el-form-item){display:block;margin:0}.create-project-form :deep(.el-input),.create-project-form :deep(.el-date-editor),.create-project-form :deep(.el-upload){width:100%}.upload-field,.remark-field{grid-column:1/-1}.selected-file-name{display:block;max-width:100%;margin-top:8px;overflow:hidden;color:#606266;text-overflow:ellipsis;white-space:nowrap}.create-project-footer{display:flex;justify-content:flex-end;gap:12px;margin-top:12px}@media (max-width:767px){.create-project-form{grid-template-columns:1fr;gap:18px}.upload-field,.remark-field{grid-column:auto}}</style>
